-- https://lua.expert/
local t = {
	Name = "Vee\'s Remote",
	Icon = "rbxassetid://17653810346",
	Rarity = "Common",
	Description = "Instantly completes the first Machine you extract from on any Floor, but only if the number of Machines completed is below 50%. Limit of 1 activation per Floor.",
	TrinketType = "Toggle",
	MonsterTrinket = true,
	Cost = 350
}

t.Requirement1 = { "Coin", t.Cost }
t.MachineEvent = true
function t.TriggerMachineEvent(p1, p2, p3) --[[ TriggerMachineEvent | Line: 31 ]]
	if not (workspace.Info.GeneratorsCompleted.Value / workspace.Info.RequiredGenerators.Value < 0.5) then
		return
	end

	local Active = p1:WaitForChild("Active")

	if Active.Value ~= true then
		return
	end

	Active.Value = false

	local CurrentAmount = p2.Stats.CurrentAmount

	CurrentAmount.Value = CurrentAmount.Value + 999

	local v1 = p2.PlayerCompletion[p3.Value.Name]

	v1.Value = v1.Value + 999
end
function t.ApplyTrinket(p1, p2) --[[ ApplyTrinket | Line: 43 ]]
	local Active = p2:WaitForChild("Active")

	workspace.Info.Floor.Changed:Connect(function() --[[ Line: 46 | Upvalues: Active (copy) ]]
		if not Active or Active.Parent == nil then
			return
		end

		Active.Value = true
	end)
	workspace.Info.GeneratorsCompleted.Changed:Connect(function() --[[ Line: 52 | Upvalues: Active (copy) ]]
		if not (workspace.Info.GeneratorsCompleted.Value / workspace.Info.RequiredGenerators.Value >= 0.5) or (not Active or Active.Parent == nil) then
			return
		end

		Active.Value = false
	end)
end
function t.RemoveTrinket(p1) --[[ RemoveTrinket | Line: 61 ]]
	local Trinkets = p1:WaitForChild("Trinkets")
	local Trinket1 = Trinkets:FindFirstChild("Trinket1")
	local Trinket2 = Trinkets:FindFirstChild("Trinket2")

	if not (Trinket1 and Trinket2) then
		return "CantRemove"
	end

	if Trinket1.Value == script.Name then
		Trinket1.Value = "None"

		return "Slot1"
	end

	if Trinket2.Value == script.Name then
		Trinket2.Value = "None"

		return "Slot2"
	end

	return "CantRemove"
end

return t